  b1Ep13BlankHint: "Três palavras: “This isn't...”",
  b1Ep13OpenInstruction: "Mostra como te sentes em relação a isso — com educação.",
  b1Ep13OpenInstruction2: "Mais uma vez — desta vez sem ajuda.",
